REGISTRY = build_registry()


def _namespace_aliases() -> dict[str, str]:
    # Keep the public namespace mapping at the catalog boundary so the
    # callable registry remains the single source of execution contracts.
    from .catalog import _module_for
    return {
        f"std.{_module_for(name)}.{name}": name
        for name in REGISTRY
    }


def signatures() -> dict[str, tuple[tuple[Any, ...], Any]]:
    result = {name: (fn.parameters, fn.result) for name, fn in REGISTRY.items()}
    for alias, name in _namespace_aliases().items():
        result[alias] = result[name]
    return result


def get(name: str) -> StdlibFunction | None:
    fn = REGISTRY.get(name)
    if fn is not None:
        return fn
    return REGISTRY.get(_namespace_aliases().get(name, ""))
